MAP
  NAME "TPW_tpw_conus_west"
  STATUS ON
  SIZE 1200 700
  EXTENT -130.0 20.0 -60.0 55.0
  UNITS DD
  IMAGECOLOR 0 0 0

  PROJECTION
    "init=epsg:4326"
  END

  WEB
    METADATA
      "wms_title"           "GOES ABI Total Precipitable Water — CONUS (GOES-18/West)"
      "wms_onlineresource"  "http://209.248.90.253/wms/tpw_conus_west"
      "wms_srs"             "EPSG:4326 EPSG:3857 EPSG:900913"
      "wms_enable_request"  "*"
      "wms_encoding"        "UTF-8"
      "wms_allow_getmap_without_styles" "true"
    END
  END

  OUTPUTFORMAT
    NAME "png"
    DRIVER "AGG/PNG"
    MIMETYPE "image/png"
    IMAGEMODE RGBA
    EXTENSION "png"
    TRANSPARENT ON
  END

  LAYER
    NAME "tpw_conus_west"
    TYPE RASTER
    STATUS ON
    DATA "/var/www/mapserver/cache/tpw_conus_west_current.tif"

    PROJECTION
      "init=epsg:4326"
    END

    PROCESSING "NODATA=nan"

    CLASS
      NAME "<10mm"
      EXPRESSION ([pixel] < 10)
      STYLE
        COLOR 140 100 60
      END
    END
    CLASS
      NAME "10-20mm"
      EXPRESSION ([pixel] >= 10 AND [pixel] < 20)
      STYLE
        COLORRANGE 190 150 90  230 220 120
        DATARANGE 10 20
      END
    END
    CLASS
      NAME "20-30mm"
      EXPRESSION ([pixel] >= 20 AND [pixel] < 30)
      STYLE
        COLORRANGE 230 220 120  140 200 100
        DATARANGE 20 30
      END
    END
    CLASS
      NAME "30-40mm"
      EXPRESSION ([pixel] >= 30 AND [pixel] < 40)
      STYLE
        COLORRANGE 140 200 100  60 170 90
        DATARANGE 30 40
      END
    END
    CLASS
      NAME "40-50mm"
      EXPRESSION ([pixel] >= 40 AND [pixel] < 50)
      STYLE
        COLORRANGE 60 170 90  40 140 190
        DATARANGE 40 50
      END
    END
    CLASS
      NAME "50-60mm"
      EXPRESSION ([pixel] >= 50 AND [pixel] < 60)
      STYLE
        COLORRANGE 40 140 190  80 60 200
        DATARANGE 50 60
      END
    END
    CLASS
      NAME "60-70mm"
      EXPRESSION ([pixel] >= 60 AND [pixel] < 70)
      STYLE
        COLORRANGE 80 60 200  200 60 200
        DATARANGE 60 70
      END
    END
    CLASS
      NAME ">=70mm"
      EXPRESSION ([pixel] >= 70)
      STYLE
        COLOR 200 60 200
      END
    END

    METADATA
      "wms_title" "GOES ABI Total Precipitable Water — CONUS (GOES-18/West)"
      "wms_srs"   "EPSG:4326 EPSG:3857"
    END
  END
END
